<template>
  <view class="page checkout safe-bottom" :style="$themeStyle">
    <view class="address card" @tap="go('/pages/address/address?select=1')"><view class="pin">⌖</view><view v-if="address" class="address-info"><text>{{address.name}}　{{address.phone}}</text><text>{{address.detail}}</text></view><view v-else class="address-info"><text>请选择收货地址</text><text>添加收货人及配送信息</text></view><text>›</text></view>
    <view class="parcel card"><view class="between parcel-head"><text>包裹 1</text><text class="muted">预计明日发货</text></view><view v-for="item in items" :key="item.key||item.id" class="order-item"><view class="art item-art" :class="'art-'+item.tone"><image v-if="item.image" class="product-image" :src="item.image" mode="aspectFill"/><text v-else class="art-icon">{{item.cover}}</text></view><view class="item-info"><text>{{item.title}}</text><text>{{item.subtitle}}</text><view class="between"><text class="price">{{item.price}}</text><text>×{{item.quantity}}</text></view></view></view>
      <view class="option between"><text>配送方式</text><text>普通快递　免运费 ›</text></view><view class="option between"><text>订单备注</text><input placeholder="选填，给商家留言"/></view>
    </view>
    <view class="summary card"><view class="between"><text>商品金额</text><text class="price">{{goodsTotal}}</text></view><view class="between"><text>运费</text><text>¥0.00</text></view><view class="between" @tap="go('/pages/coupons/coupons?select=1')"><text>优惠券</text><text class="accent">- ¥{{discount.toFixed(2)}} ›</text></view><view class="between"><text>积分抵扣</text><switch :color="$themeAccent" :checked="usePoints" @change="usePoints=$event.detail.value"/></view><view class="between total-line"><text>应付合计</text><text class="price">{{finalTotal}}</text></view></view>
    <view class="agree"><text>提交订单即代表您同意《购买须知》</text></view>
    <view class="submit-bar"><view><text>共 {{count}} 件，合计</text><text class="price">{{finalTotal}}</text></view><button @tap="submit">提交订单</button></view>
  </view>
</template>
<script setup>
import {ref,computed} from 'vue';import{onLoad,onShow}from'@dcloudio/uni-app';import{getCart}from'../../utils/shop';import{getDefaultAddress}from'../../utils/address'
const items=ref([]),address=ref(null),usePoints=ref(false),discount=ref(15),from=ref('');onLoad(o=>{from.value=o.from||'';items.value=from.value==='buy'?(uni.getStorageSync('buy_now')||[]):getCart().filter(v=>v.checked)});onShow(()=>address.value=uni.getStorageSync('selected_address')||getDefaultAddress());
const goodsTotal=computed(()=>items.value.reduce((s,v)=>s+v.price*v.quantity,0).toFixed(2));const count=computed(()=>items.value.reduce((s,v)=>s+v.quantity,0));const finalTotal=computed(()=>Math.max(0,Number(goodsTotal.value)-discount.value-(usePoints.value?5:0)).toFixed(2));const go=url=>uni.navigateTo({url});
const submit=()=>{if(!address.value)return uni.showToast({title:'请先添加收货地址',icon:'none'});const order={id:'WM'+Date.now().toString().slice(-8),items:items.value,total:finalTotal.value,status:'待付款',createdAt:'2026-10-06 12:30',address:address.value};uni.setStorageSync('pending_order',order);go('/pages/payment/payment')}
</script>
<style scoped>
.checkout{padding-top:22rpx;padding-bottom:160rpx}.address{padding:32rpx;display:flex;align-items:center;border-bottom:5rpx solid transparent;border-image:repeating-linear-gradient(90deg,#c86b54 0 20rpx,transparent 20rpx 32rpx,#637b6c 32rpx 52rpx,transparent 52rpx 64rpx) 5}.pin{font-size:38rpx;margin-right:20rpx}.address-info{flex:1}.address-info text{display:block}.address-info text:first-child{font-weight:700}.address-info text+text{font-size:23rpx;color:var(--muted);line-height:1.5;margin-top:10rpx}.parcel,.summary{padding:28rpx;margin-top:22rpx}.parcel-head{font-weight:700;margin-bottom:15rpx}.parcel-head .muted{font-size:21rpx;font-weight:400}.order-item{display:flex;padding:18rpx 0;border-bottom:1rpx solid var(--line)}.item-art{width:150rpx;height:150rpx;border-radius:18rpx;margin-right:20rpx}.item-art .art-icon{font-size:55rpx}.item-info{flex:1}.item-info>text{display:block}.item-info>text:first-child{font-weight:600}.item-info>text:nth-child(2){font-size:21rpx;color:var(--muted);margin-top:10rpx}.item-info>view{margin-top:25rpx}.option{padding-top:27rpx}.option input{text-align:right;font-size:25rpx}.summary>view{margin-bottom:27rpx}.summary>view:last-child{margin:0}.total-line{border-top:1rpx solid var(--line);padding-top:28rpx;font-weight:700}.total-line .price{font-size:36rpx}.agree{text-align:center;color:#aaa;font-size:20rpx;margin:30rpx}.submit-bar{position:fixed;z-index:9;bottom:0;left:0;right:0;background:#fff;padding:18rpx 24rpx calc(18rpx + env(safe-area-inset-bottom));display:flex;align-items:center;justify-content:flex-end}.submit-bar>view{text-align:right}.submit-bar>view text{display:block;font-size:20rpx}.submit-bar .price{font-size:35rpx;color:var(--accent)}.submit-bar button{margin:0 0 0 24rpx;background:var(--ink);color:#fff;border-radius:50rpx;padding:0 42rpx;font-size:26rpx}
</style>
